assert len(NOTES)==41
native=json.loads((ROOT/'pins_head/cranial-native-features.json').read_text(encoding='utf-8'))
bycode={}
for marker in native['markers']:bycode.setdefault(marker['c'],[]).append(marker)
rows=[]
for (b,c),pos in positions().items():
 if b not in BONES or pos['localization']!='projection':continue
 ms=bycode.get(c,[]);base=b.split('_')[0]
 scopes=sorted({m['scope'] for m in ms})
 paths={'frontal':['jobs/frontal-ant.png','jobs/frontal-inf.png','jobs/frontal-posterior.png','jobs_ct/frontal-orbits.png'],'parietal':['jobs/'+b+'-lat.png','jobs/'+b+'-med.png'],'occipital':['jobs/occipital-inf.png','jobs/occipital-internal.png','jobs/occipital-channel-left.png','jobs/occipital-channel-right.png','jobs_ct/occipital-base.png','jobs_ct/occipital-internal-oblique.png'],'sphenoid':['jobs/sphenoid-sup.png','jobs/sphenoid-inf.png','jobs/sphenoid-ant.png','jobs/sphenoid-pterygoid-back.png','jobs/sphenoid-optic-oblique.png','jobs/sphenoid-ant-medial.png'],'ethmoid':['jobs/ethmoid-sup.png','jobs/ethmoid-lat.png','jobs/ethmoid-med.png','jobs_roi/sup.png','jobs_roi/ant.png']}[base]
 rows.append({'bone':b,'code':c,'ru':T[c][1],'lat':T[c][0],'primaryLocalization':'projection','anatomicalFactReferences':DESCRIPTIONS[c]['refs'],'geometryStatus':'source-airspace-only' if scopes==['airspace'] else 'source-aperture-only' if scopes==['aperture'] else 'not-confirmed','fullBonyGeometryConfirmed':False,'nativeMarkerIds':[m['id'] for m in ms],'observation':NOTES[c],'reviewImages':['build_head/cranial_features/'+s for s in paths],'requiredNextEvidence':'For a channel: both openings and continuous native walls; for relief: a recognizable original surface; for an airspace: independently verified bounding bone and communications. Regional inspection is not a complete voxel-by-voxel review.'})
assert len(rows)==45
out={'date':'2026-10-13','projectionRecords':45,'uniqueTA98Terms':41,'summary':dict(Counter(r['geometryStatus'] for r in rows)),'completeGeometryClaim':False,'nativeMarkers':len(native['markers']),'uniqueNativeMarkerTerms':len(bycode),'notes':['12 новых собственных маркеров относятся к 7 терминам; 8 объёмов полостей соответствуют только 5 разным терминам.','Ни один из 45 статусов BodyParts3D не изменён. Частичное подтверждение апертуры и учебная модель пространства не считаются полным костным каналом.','Неподтверждённый статус означает недостаточность выполненной проверки, не доказанное отсутствие образования у человека или во всех доступных источниках.'], 'halleSourceROI':{'originalSource':'https://zenodo.org/records/6108435','sourceMD5':'7ae22945a353069bdb695b63fa2f20bd','sampling_mm':.125,'processing':'Binary source mask at its original resolution; ROI, marching cubes 0.5; no smoothing, filling or invented geometry.','provenance':'build_head/cranial_features/halle-roi-provenance.json','published':False,'reason':'The source mask ROI does not resolve the distinction between true fine foramina and segmentation/preparation defects with sufficient confidence; publishing it would not close the target feature list.'},'rows':rows}
(ROOT/'research/cranial-feature-review.json').write_text(json.dumps(out,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
print(len(rows),dict(Counter(r['geometryStatus'] for r in rows)))
